openProject('<project root>\Shaddad_UGV.prj');
% 1) straight run at 0.8 m/s on the dry-sand strip of soil_strips (world 6)
res = phase1_test_drive('World', 6, 'Plan', [0 0 0; 4 0.8 0; 40 0 0]);

% 2) structure signals of a Phase 1 run
res = phase1_test_drive('Replay', false);
S = res.S;
figure; plot(S.truth.slip_LR.t, 100*S.truth.slip_LR.v);
ylabel('belt slip [%]'); legend('left', 'right');
figure; plot(S.truth.pose2D.v(:,1), S.truth.pose2D.v(:,2)); axis equal;   % path of R, site ENU
chi = S.struct_diag.chi_eff.v;     % NaN while |r| < 0.05 rad/s

% 3) HiFi bench: both belts ramp to 1 m/s on farm soil, 10 s
[P, Ts] = shaddad_params('World', 1, 'Assign', false);
P.structure.init = structure_initial_state(P, 'Soil', 2);
tbs = tb_structure_defaults(P);
tbs.envovr.use_soil = true;  tbs.envovr.soil_id = uint8(2);
rs = P.structure.r_sprocket;
tbs.t = [0 1 1e3];  tbs.uL = [0 1 1]/rs;  tbs.uR = [0 1 1]/rs;  tbs.rref = [0 0 0];
out = structure_tb_run(P, Ts, tbs, 'StopTime', 10);          % 'Fid', 2 for LoFi
[t, s] = structure_tb_signal(out.tb_tracks.slip);  plot(t, 100*s)
